  const GEMS = [{"id": "gem-stonska-torta", "pattern": "stonska torta", "tag": "Ston gem · born here", "name": "A pasta cake for wall-builders", "story": "Ston’s own cake is the strangest sweet on the coast: cooked macaroni folded with ground walnuts, dark chocolate, lemon zest, cinnamon and sugar, baked in shortcrust. Tradition ties it to the building of the Ston walls in the fourteenth century, as dense food for the labourers; nobody has a document for that, and the cake has long since become a wedding and feast-day dish.", "where": "Ston and Mali Ston, an hour north; ask at the oyster houses."}, {"id": "gem-arancini", "pattern": "arancini", "tag": "City gem · born here", "name": "Not a rice ball", "story": "In Dubrovnik arancini are not the fried rice of the south of Italy but candied bitter-orange peel: the peel boiled to take out the bitterness, dried, candied and rolled in sugar, kept in jars for feasts and guests. The bitter orange came to the Mediterranean with the Arabs; the city made a confection of the part everyone else threw away.", "where": "The Gundulić Square market, in the morning."}, {"id": "gem-rozalin", "pattern": "Rozalin", "tag": "City gem · born here", "name": "A rose in the bottle", "story": "Rozalin, or rozulin, is the city’s home-made rose-petal liqueur, steeped from garden roses in spirit and sugar. It is what turns the rožata from a crème caramel into a Dubrovnik dish, and a small glass of it closes a meal in the old houses.", "where": "The old houses of the Old Town, after dinner; and in the rožata."}];
